import React, {
  useEffect,
  useRef,
  useState,
} from 'react';

import { toast } from 'react-toastify';

import {
  FiPlus,
  FiEdit2,
  FiTrash2,
  FiStar,
  FiImage,
  FiMessageSquare,
  FiUser,
  FiCheckCircle,
} from 'react-icons/fi';

import api from '../../services/api';
import { getImageUrl } from '../../utils/helpers';

import AdminTable from '../common/AdminTable';
import AdminModal from '../common/AdminModal';
import AdminCard from '../common/AdminCard';

import {
  useLanguage,
} from '../../contexts/LanguageContext';


const DEFAULT_AVATAR =
  '/default-avatar.png';


const initialForm = {
  name: '',
  role: '',
  content: '',
  rating: 5,
  is_active: true,
  order: 0,
};


const AdminTestimonials = () => {

  const {
    t,
    language,
  } = useLanguage();


  const isKhmer =
    language === 'km';


  const [
    testimonials,
    setTestimonials,
  ] = useState([]);


  const [
    loading,
    setLoading,
  ] = useState(true);


  const [
    modalOpen,
    setModalOpen,
  ] = useState(false);


  const [
    editingTestimonial,
    setEditingTestimonial,
  ] = useState(null);


  const [
    formData,
    setFormData,
  ] = useState(initialForm);


  const [
    avatarFile,
    setAvatarFile,
  ] = useState(null);


  const [
    avatarPreview,
    setAvatarPreview,
  ] = useState(null);


  const fileInputRef =
    useRef(null);


  useEffect(() => {
    fetchTestimonials();

    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);


  useEffect(() => {

    return () => {

      if (
        avatarPreview &&
        avatarPreview.startsWith('blob:')
      ) {
        URL.revokeObjectURL(
          avatarPreview
        );
      }

    };

  }, [avatarPreview]);


  const fetchTestimonials =
    async () => {

      try {

        setLoading(true);


        const response =
          await api.get(
            '/api/testimonials/'
          );


        setTestimonials(
          Array.isArray(response.data)
            ? response.data
            : []
        );

      } catch (error) {

        console.error(
          'Fetch testimonials error:',
          error
        );


        toast.error(
          error.response?.data?.detail ||
          t(
            'testimonials.loadFailed'
          )
        );

      } finally {

        setLoading(false);

      }

    };


  const resetForm = () => {

    setEditingTestimonial(
      null
    );


    setFormData({
      name: '',
      role: '',
      content: '',
      rating: 5,
      is_active: true,
      order: 0,
    });


    setAvatarFile(null);


    if (
      avatarPreview &&
      avatarPreview.startsWith('blob:')
    ) {
      URL.revokeObjectURL(
        avatarPreview
      );
    }


    setAvatarPreview(null);


    if (
      fileInputRef.current
    ) {
      fileInputRef.current.value =
        '';
    }

  };


  const openCreateModal = () => {

    resetForm();

    setModalOpen(true);

  };


  const closeModal = () => {

    setModalOpen(false);

    resetForm();

  };


  const handleAvatarChange =
    (e) => {

      const file =
        e.target.files?.[0];


      if (!file) {
        return;
      }


      const allowedTypes = [
        'image/jpeg',
        'image/png',
        'image/webp',
      ];


      if (
        !allowedTypes.includes(
          file.type
        )
      ) {

        toast.error(
          t(
            'testimonials.invalidImage'
          )
        );

        e.target.value = '';

        return;

      }


      const maxSize =
        5 * 1024 * 1024;


      if (
        file.size > maxSize
      ) {

        toast.error(
          t(
            'testimonials.imageTooLarge'
          )
        );

        e.target.value = '';

        return;

      }


      if (
        avatarPreview &&
        avatarPreview.startsWith(
          'blob:'
        )
      ) {
        URL.revokeObjectURL(
          avatarPreview
        );
      }


      setAvatarFile(file);


      setAvatarPreview(
        URL.createObjectURL(
          file
        )
      );

    };


  const handleSubmit =
    async (e) => {

      e.preventDefault();


      if (
        !formData.name.trim()
      ) {

        toast.error(
          t(
            'testimonials.nameRequired'
          )
        );

        return;

      }


      if (
        !formData.content.trim()
      ) {

        toast.error(
          t(
            'testimonials.contentRequired'
          )
        );

        return;

      }


      try {

        const data =
          new FormData();


        data.append(
          'name',
          formData.name.trim()
        );


        data.append(
          'role',
          formData.role?.trim() ||
          ''
        );


        data.append(
          'content',
          formData.content.trim()
        );


        data.append(
          'rating',
          String(
            formData.rating
          )
        );


        data.append(
          'is_active',
          String(
            formData.is_active
          )
        );


        data.append(
          'order',
          String(
            formData.order
          )
        );


        if (avatarFile) {

          data.append(
            'avatar',
            avatarFile
          );

        }


        if (
          editingTestimonial
        ) {

          await api.put(
            `/api/testimonials/${editingTestimonial.id}`,
            data,
            {
              headers: {
                'Content-Type':
                  'multipart/form-data',
              },
            }
          );


          toast.success(
            t(
              'testimonials.updatedSuccess'
            )
          );

        } else {

          await api.post(
            '/api/testimonials/',
            data,
            {
              headers: {
                'Content-Type':
                  'multipart/form-data',
              },
            }
          );


          toast.success(
            t(
              'testimonials.createdSuccess'
            )
          );

        }


        setModalOpen(false);

        resetForm();

        await fetchTestimonials();

      } catch (error) {

        console.error(
          'Testimonial submit error:',
          error
        );


        const detail =
          error.response?.data
            ?.detail ||
          error.response?.data
            ?.message;


        if (
          Array.isArray(detail)
        ) {

          toast.error(
            detail
              .map(
                (item) =>
                  item?.msg ||
                  t(
                    'testimonials.operationFailed'
                  )
              )
              .join(', ')
          );

        } else {

          toast.error(
            detail ||
            t(
              'testimonials.operationFailed'
            )
          );

        }

      }

    };


  const handleDelete =
    async (id) => {

      const confirmDelete =
        window.confirm(
          t(
            'testimonials.deleteConfirm'
          )
        );


      if (!confirmDelete) {
        return;
      }


      try {

        await api.delete(
          `/api/testimonials/${id}`
        );


        toast.success(
          t(
            'testimonials.deletedSuccess'
          )
        );


        await fetchTestimonials();

      } catch (error) {

        console.error(
          'Delete testimonial error:',
          error
        );


        toast.error(
          error.response?.data
            ?.detail ||
          t(
            'testimonials.deleteFailed'
          )
        );

      }

    };


  const handleEdit =
    (testimonial) => {

      setEditingTestimonial(
        testimonial
      );


      setFormData({

        name:
          testimonial.name ||
          '',

        role:
          testimonial.role ||
          '',

        content:
          testimonial.content ||
          '',

        rating:
          testimonial.rating ||
          5,

        is_active:
          testimonial.is_active ??
          true,

        order:
          testimonial.order ||
          0,

      });


      setAvatarFile(null);


      if (
        avatarPreview &&
        avatarPreview.startsWith(
          'blob:'
        )
      ) {
        URL.revokeObjectURL(
          avatarPreview
        );
      }


      setAvatarPreview(null);


      if (
        fileInputRef.current
      ) {
        fileInputRef.current.value =
          '';
      }


      setModalOpen(true);

    };


  const renderStars =
    (rating) => {

      const safeRating =
        Math.max(
          0,
          Math.min(
            5,
            Number(rating) || 0
          )
        );


      return (
        <div
          className="
            flex
            items-center
            gap-1
          "
        >

          {
            [...Array(5)].map(
              (_, index) => (

                <FiStar
                  key={index}

                  size={16}

                  className={
                    index <
                    safeRating
                      ? `
                        text-red-600
                        fill-current
                      `
                      : 'text-blue-300'
                  }
                />

              )
            )
          }

        </div>
      );

    };


  const columns = [

    {
      key: 'avatar',

      label:
        t(
          'testimonials.avatar'
        ),

      render: (value) => (

        <div
          className="
            w-14
            h-14

            rounded-xl

            overflow-hidden

            border
            border-blue-200

            bg-blue-50

            shadow-sm
          "
        >

          <img
            src={
              getImageUrl(
                value,
                DEFAULT_AVATAR
              )
            }

            alt={
              t(
                'testimonials.avatar'
              )
            }

            className="
              w-full
              h-full

              object-cover
            "

            onError={(e) => {
              e.currentTarget.src =
                DEFAULT_AVATAR;
            }}
          />

        </div>

      ),
    },


    {
      key: 'name',

      label:
        t(
          'testimonials.name'
        ),

      render: (value) => (

        <div
          className="
            flex
            items-center
            gap-3
          "
        >

          <div
            className="
              w-9
              h-9

              flex
              items-center
              justify-center

              rounded-lg

              bg-blue-50
              text-blue-900

              flex-shrink-0
            "
          >

            <FiUser
              size={17}
            />

          </div>


          <p
            className="
              font-semibold
              text-blue-900
            "
          >
            {value || '-'}
          </p>

        </div>

      ),
    },


    {
      key: 'role',

      label:
        t(
          'testimonials.role'
        ),

      render: (value) => (

        <span
          className="
            inline-flex

            px-3
            py-1.5

            rounded-full

            bg-blue-50
            text-blue-900

            border
            border-blue-200

            text-xs
            font-medium
          "
        >
          {value || '-'}
        </span>

      ),
    },


    {
      key: 'content',

      label:
        t(
          'testimonials.content'
        ),

      render: (value) => (

        <p
          className="
            max-w-xs

            text-sm
            text-blue-500

            line-clamp-2

            leading-5
          "
        >
          {value || '-'}
        </p>

      ),
    },


    {
      key: 'rating',

      label:
        t(
          'testimonials.rating'
        ),

      render: (value) => (

        <div
          className="
            space-y-1
          "
        >

          {
            renderStars(
              value
            )
          }


          <span
            className="
              text-xs
              text-blue-300
            "
          >
            {value || 0}/5
          </span>

        </div>

      ),
    },


    {
      key: 'is_active',

      label:
        t(
          'common.status'
        ),

      render: (value) => (

        <span
          className={`
            inline-flex
            items-center
            gap-2

            px-3
            py-1.5

            rounded-full

            text-xs
            font-semibold

            border

            ${
              value
                ? `
                  bg-blue-50
                  text-blue-700
                  border-blue-200
                `
                : `
                  bg-red-50
                  text-red-600
                  border-red-200
                `
            }
          `}
        >

          <span
            className={`
              w-2
              h-2

              rounded-full

              ${
                value
                  ? 'bg-blue-500'
                  : 'bg-red-500'
              }
            `}
          />


          {
            value
              ? t(
                  'common.active'
                )
              : t(
                  'common.inactive'
                )
          }

        </span>

      ),
    },


    {
      key: 'actions',

      label:
        t(
          'common.actions'
        ),

      render: (_, row) => (

        <div
          className="
            flex
            items-center
            gap-2
          "
        >

          <button
            type="button"

            onClick={() =>
              handleEdit(row)
            }

            title={
              t(
                'testimonials.editTestimonial'
              )
            }

            className="
              w-9
              h-9

              flex
              items-center
              justify-center

              rounded-lg

              bg-blue-50
              text-blue-900

              hover:bg-blue-900
              hover:text-white

              transition-all
              duration-200
            "
          >

            <FiEdit2
              size={16}
            />

          </button>


          <button
            type="button"

            onClick={() =>
              handleDelete(
                row.id
              )
            }

            title={
              t(
                'testimonials.deleteTestimonial'
              )
            }

            className="
              w-9
              h-9

              flex
              items-center
              justify-center

              rounded-lg

              bg-red-50
              text-red-600

              hover:bg-red-600
              hover:text-white

              transition-all
              duration-200
            "
          >

            <FiTrash2
              size={16}
            />

          </button>

        </div>

      ),
    },

  ];


  return (

    <div
      className={`
        w-full

        ${
          isKhmer
            ? 'font-khmer'
            : 'font-english'
        }
      `}
    >

      <div
        className="
          flex
          flex-col

          sm:flex-row
          sm:items-center
          sm:justify-between

          gap-4

          mb-7
        "
      >

        <div
          className="
            flex
            items-center
            gap-3
          "
        >

          <div
            className="
              w-12
              h-12

              flex
              items-center
              justify-center

              rounded-xl

              bg-blue-900
              text-white

              shadow-sm
            "
          >

            <FiMessageSquare
              size={22}
            />

          </div>


          <div>

            <h1
              className="
                text-2xl
                md:text-3xl

                font-bold

                text-blue-900

                leading-tight
              "
            >
              {t(
                'testimonials.title'
              )}
            </h1>


            <p
              className="
                text-sm
                text-blue-400

                mt-1
              "
            >
              {t(
                'testimonials.subtitle'
              )}
            </p>

          </div>

        </div>


        <button
          type="button"

          onClick={
            openCreateModal
          }

          className="
            inline-flex
            items-center
            justify-center
            gap-2

            h-11

            px-5

            bg-red-600
            hover:bg-red-700

            text-white

            rounded-xl

            text-sm
            font-semibold

            shadow-sm
            hover:shadow-md

            transition-all
            duration-200
          "
        >

          <FiPlus
            size={18}
          />

          {t(
            'testimonials.addTestimonial'
          )}

        </button>

      </div>


      <AdminCard
        className="
          overflow-hidden

          bg-white

          border
          border-blue-200

          rounded-2xl

          shadow-sm
        "
      >

        <AdminTable
          columns={columns}

          data={
            testimonials
          }

          loading={
            loading
          }
        />

      </AdminCard>


      <AdminModal
        isOpen={
          modalOpen
        }

        onClose={
          closeModal
        }

        title={
          editingTestimonial
            ? t(
                'testimonials.editTestimonial'
              )
            : t(
                'testimonials.createTestimonial'
              )
        }
      >

        <div
          className={
            isKhmer
              ? 'font-khmer'
              : 'font-english'
          }
        >

          <form
            onSubmit={
              handleSubmit
            }
          >

            <div
              className="
                space-y-5
              "
            >

              <div
                className="
                  grid
                  grid-cols-1

                  md:grid-cols-2

                  gap-4
                "
              >

                <div>

                  <label
                    className="
                      block

                      text-sm
                      font-semibold

                      text-blue-900

                      mb-1.5
                    "
                  >

                    {t(
                      'testimonials.name'
                    )}

                    <span
                      className="
                        text-red-600
                        ml-1
                      "
                    >
                      *
                    </span>

                  </label>


                  <input
                    type="text"

                    value={
                      formData.name
                    }

                    onChange={(e) =>
                      setFormData({
                        ...formData,
                        name:
                          e.target.value,
                      })
                    }

                    placeholder={
                      t(
                        'testimonials.namePlaceholder'
                      )
                    }

                    required

                    className="
                      w-full

                      px-4
                      py-2.5

                      border
                      border-blue-200

                      rounded-xl

                      bg-white

                      text-blue-900

                      placeholder:text-blue-300

                      focus:outline-none
                      focus:ring-2
                      focus:ring-blue-900/20
                      focus:border-blue-900

                      transition-all
                      duration-200
                    "
                  />

                </div>


                <div>

                  <label
                    className="
                      block

                      text-sm
                      font-semibold

                      text-blue-900

                      mb-1.5
                    "
                  >
                    {t(
                      'testimonials.role'
                    )}
                  </label>


                  <input
                    type="text"

                    value={
                      formData.role
                    }

                    onChange={(e) =>
                      setFormData({
                        ...formData,
                        role:
                          e.target.value,
                      })
                    }

                    placeholder={
                      t(
                        'testimonials.rolePlaceholder'
                      )
                    }

                    className="
                      w-full

                      px-4
                      py-2.5

                      border
                      border-blue-200

                      rounded-xl

                      bg-white

                      text-blue-900

                      placeholder:text-blue-300

                      focus:outline-none
                      focus:ring-2
                      focus:ring-blue-900/20
                      focus:border-blue-900

                      transition-all
                      duration-200
                    "
                  />

                </div>

              </div>


              <div>

                <label
                  className="
                    block

                    text-sm
                    font-semibold

                    text-blue-900

                    mb-1.5
                  "
                >

                  {t(
                    'testimonials.content'
                  )}

                  <span
                    className="
                      text-red-600
                      ml-1
                    "
                  >
                    *
                  </span>

                </label>


                <textarea
                  value={
                    formData.content
                  }

                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      content:
                        e.target.value,
                    })
                  }

                  rows={5}

                  required

                  placeholder={
                    t(
                      'testimonials.contentPlaceholder'
                    )
                  }

                  className="
                    w-full

                    px-4
                    py-3

                    border
                    border-blue-200

                    rounded-xl

                    bg-white

                    text-blue-900

                    placeholder:text-blue-300

                    resize-y

                    focus:outline-none
                    focus:ring-2
                    focus:ring-blue-900/20
                    focus:border-blue-900

                    transition-all
                    duration-200
                  "
                />

              </div>


              <div
                className="
                  grid
                  grid-cols-1

                  md:grid-cols-2

                  gap-4
                "
              >

                <div>

                  <label
                    className="
                      block

                      text-sm
                      font-semibold

                      text-blue-900

                      mb-1.5
                    "
                  >
                    {t(
                      'testimonials.rating'
                    )}
                  </label>


                  <select
                    value={
                      formData.rating
                    }

                    onChange={(e) =>
                      setFormData({
                        ...formData,
                        rating:
                          Number(
                            e.target.value
                          ),
                      })
                    }

                    className="
                      w-full

                      px-4
                      py-2.5

                      border
                      border-blue-200

                      rounded-xl

                      bg-white

                      text-blue-900

                      focus:outline-none
                      focus:ring-2
                      focus:ring-blue-900/20
                      focus:border-blue-900

                      transition-all
                      duration-200
                    "
                  >

                    <option value={5}>
                      5
                    </option>

                    <option value={4}>
                      4
                    </option>

                    <option value={3}>
                      3
                    </option>

                    <option value={2}>
                      2
                    </option>

                    <option value={1}>
                      1
                    </option>

                  </select>

                </div>


                <div>

                  <label
                    className="
                      block

                      text-sm
                      font-semibold

                      text-blue-900

                      mb-1.5
                    "
                  >
                    {t(
                      'testimonials.order'
                    )}
                  </label>


                  <input
                    type="number"

                    min="0"

                    value={
                      formData.order
                    }

                    onChange={(e) =>
                      setFormData({
                        ...formData,
                        order:
                          Number(
                            e.target.value
                          ),
                      })
                    }

                    className="
                      w-full

                      px-4
                      py-2.5

                      border
                      border-blue-200

                      rounded-xl

                      bg-white

                      text-blue-900

                      focus:outline-none
                      focus:ring-2
                      focus:ring-blue-900/20
                      focus:border-blue-900

                      transition-all
                      duration-200
                    "
                  />

                </div>

              </div>


              <div>

                <label
                  className="
                    block

                    text-sm
                    font-semibold

                    text-blue-900

                    mb-2
                  "
                >
                  {t(
                    'testimonials.avatar'
                  )}
                </label>


                <div
                  className="
                    flex
                    flex-col

                    sm:flex-row
                    sm:items-center

                    gap-4
                  "
                >

                  <div
                    className="
                      w-24
                      h-24

                      rounded-2xl

                      overflow-hidden

                      bg-blue-50

                      border
                      border-blue-200

                      flex
                      items-center
                      justify-center

                      flex-shrink-0
                    "
                  >

                    {
                      avatarPreview ||
                      editingTestimonial
                        ?.avatar
                        ? (

                          <img
                            src={
                              avatarPreview ||
                              getImageUrl(
                                editingTestimonial
                                  ?.avatar,
                                DEFAULT_AVATAR
                              )
                            }

                            alt={
                              t(
                                'testimonials.avatar'
                              )
                            }

                            className="
                              w-full
                              h-full

                              object-cover
                            "

                            onError={(e) => {
                              e.currentTarget.src =
                                DEFAULT_AVATAR;
                            }}
                          />

                        )
                        : (

                          <FiImage
                            size={30}

                            className="
                              text-blue-300
                            "
                          />

                        )
                    }

                  </div>


                  <div
                    className="
                      flex-1
                    "
                  >

                    <input
                      ref={
                        fileInputRef
                      }

                      type="file"

                      accept="
                        image/jpeg,
                        image/png,
                        image/webp
                      "

                      onChange={
                        handleAvatarChange
                      }

                      className="
                        block
                        w-full

                        text-sm
                        text-blue-500

                        file:mr-4
                        file:py-2
                        file:px-4

                        file:rounded-lg
                        file:border-0

                        file:bg-blue-50
                        file:text-blue-900

                        file:font-semibold

                        hover:file:bg-blue-100

                        cursor-pointer
                      "
                    />


                    <p
                      className="
                        text-xs
                        text-blue-300

                        mt-2
                      "
                    >
                      {t(
                        'testimonials.imageHint'
                      )}
                    </p>

                  </div>

                </div>

              </div>


              <div
                className="
                  flex
                  items-center
                  justify-between

                  gap-4

                  p-4

                  rounded-xl

                  bg-blue-50

                  border
                  border-blue-100
                "
              >

                <div
                  className="
                    flex
                    items-center
                    gap-3
                  "
                >

                  <div
                    className="
                      w-10
                      h-10

                      rounded-lg

                      bg-white

                      flex
                      items-center
                      justify-center

                      text-blue-900

                      border
                      border-blue-100
                    "
                  >
                    <FiCheckCircle
                      size={19}
                    />
                  </div>


                  <div>

                    <p
                      className="
                        text-sm
                        font-semibold
                        text-blue-900
                      "
                    >
                      {t(
                        'common.status'
                      )}
                    </p>


                    <p
                      className="
                        text-xs
                        text-blue-400

                        mt-0.5
                      "
                    >
                      {
                        formData.is_active
                          ? t(
                              'common.active'
                            )
                          : t(
                              'common.inactive'
                            )
                      }
                    </p>

                  </div>

                </div>


                <button
                  type="button"

                  onClick={() =>
                    setFormData({
                      ...formData,
                      is_active:
                        !formData.is_active,
                    })
                  }

                  className={`
                    relative

                    inline-flex

                    h-7
                    w-12
leadership.members
                    flex-shrink-0

                    cursor-pointer

                    rounded-full

                    transition-colors
                    duration-200

                    focus:outline-none

                    ${
                      formData.is_active
                        ? 'bg-blue-900'
                        : 'bg-blue-200'
                    }
                  `}
                >

                  <span
                    className={`
                      pointer-events-none

                      inline-block

                      h-5
                      w-5

                      mt-1

                      rounded-full

                      bg-white

                      shadow

                      transform

                      transition-transform
                      duration-200

                      ${
                        formData.is_active
                          ? 'translate-x-6'
                          : 'translate-x-1'
                      }
                    `}
                  />

                </button>

              </div>

            </div>


            <div
              className="
                flex
                flex-col-reverse

                sm:flex-row
                sm:justify-end

                gap-3

                mt-7

                pt-5

                border-t
                border-blue-100
              "
            >

              <button
                type="button"

                onClick={
                  closeModal
                }

                className="
                  px-5
                  py-2.5

                  rounded-xl

                  border
                  border-blue-200

                  bg-white

                  text-blue-700

                  text-sm
                  font-semibold

                  hover:bg-blue-50

                  transition-all
                  duration-200
                "
              >
                {t(
                  'common.cancel'
                )}
              </button>


              <button
                type="submit"

                className="
                  inline-flex
                  items-center
                  justify-center
                  gap-2

                  px-5
                  py-2.5

                  rounded-xl

                  bg-red-600
                  hover:bg-red-700

                  text-white

                  text-sm
                  font-semibold

                  shadow-sm

                  transition-all
                  duration-200
                "
              >

                {
                  editingTestimonial
                    ? (
                      <>
                        <FiEdit2
                          size={16}
                        />

                        {t(
                          'common.update'
                        )}
                      </>
                    )
                    : (
                      <>
                        <FiPlus
                          size={16}
                        />

                        {t(
                          'common.create'
                        )}
                      </>
                    )
                }

              </button>

            </div>

          </form>

        </div>

      </AdminModal>

    </div>

  );

};


export default AdminTestimonials;
